const MemorialAIPage = () => {
  const [activeTab, setActiveTab] = useState<'generate' | 'chat'>('generate');
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const [chatMessages, setChatMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [chatInput, setChatInput] = useState('');

  const generateConcept = async () => {
    if (!prompt) return;
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: [{ text: `A photorealistic, highly detailed memorial tombstone or funeral floral arrangement. Theme: ${prompt}. High resolution, cinematic lighting, architectural style.` }] },
        config: { imageConfig: { aspectRatio: "1:1" } }
      });

      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          setResultImage(`data:image/png;base64,${part.inlineData.data}`);
          break;
        }
      }
    } catch (err) {
      console.error(err);
      alert('Failed to generate. Please try a different prompt.');
    } finally {
      setIsGenerating(false);
    }
  };

  const handleChat = async () => {
    if (!chatInput) return;
    const userMsg = chatInput;
    setChatInput('');
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMsg,
        config: { systemInstruction: "You are the CloverLeaf Compassionate Guide. You help families with funeral planning, grief support, and memorial ideas with a calm, empathetic, and professional tone." }
      });
      setChatMessages(prev => [...prev, { role: 'ai', text: response.text || "I'm here to support you. How else can I help?" }]);
    } catch (err) {
      setChatMessages(prev => [...prev, { role: 'ai', text: "I'm having trouble connecting, but I'm still here for you." }]);
    }
  };

  return (
    <div className="pt-32 pb-24 px-4 max-w-7xl mx-auto">
      <div className="flex items-center justify-between mb-12">
        <h2 className="text-5xl font-black tracking-tighter">MEMORIAL AI</h2>
        <div className="bg-gray-100 dark:bg-white/5 p-1 rounded-2xl flex gap-1">
          <button 
            onClick={() => setActiveTab('generate')}
            className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${activeTab === 'generate' ? 'bg-white dark:bg-forest text-black dark:text-white shadow-sm' : 'opacity-50'}`}
          >
            GENERATE CONCEPT
          </button>
          <button 
            onClick={() => setActiveTab('chat')}
            className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${activeTab === 'chat' ? 'bg-white dark:bg-forest text-black dark:text-white shadow-sm' : 'opacity-50'}`}
          >
            COMPASSIONATE GUIDE
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 min-h-[600px]">
        {activeTab === 'generate' ? (
          <>
            <div className="lg:col-span-4 space-y-8">
              <div className="p-8 bg-white dark:bg-black/20 border border-gray-100 dark:border-white/5 rounded-[2.5rem]">
                <label className="block text-xs font-black uppercase tracking-widest text-forest mb-4">Design Concept</label>
                <textarea 
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  className="w-full h-40 bg-gray-50 dark:bg-black/40 border-0 rounded-2xl p-6 text-sm resize-none focus:ring-2 focus:ring-forest outline-none transition-all"
                  placeholder="e.g. A white marble memorial with cascading ivy and a minimalist architectural finish..."
                />
                <div className="mt-6 flex items-center justify-between text-[10px] font-bold text-gray-400">
                  <span>MODEL: GEMINI 2.5 FLASH</span>
                  <span>PREVIEW: 1K HD</span>
                </div>
                <button 
                  onClick={generateConcept}
                  disabled={isGenerating}
                  className="w-full mt-6 py-4 bg-forest text-white font-black rounded-2xl shadow-xl shadow-forest/20 disabled:opacity-50 hover:scale-[1.01] active:scale-[0.99] transition-all flex items-center justify-center gap-2"
                >
                  {isGenerating ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <ImageIcon size={20} />}
                  {isGenerating ? 'VISUALIZING...' : 'GENERATE DESIGN'}
                </button>
              </div>
              <div className="p-6 bg-forest/5 rounded-[2rem] border border-forest/10">
                <h4 className="text-xs font-black uppercase text-forest mb-2">Pro Tip</h4>
                <p className="text-xs text-gray-500 leading-relaxed">Try adding words like "Granite", "Italian Marble", or "Floral Tribute" for better results.</p>
              </div>
            </div>
            <div className="lg:col-span-8 bg-gray-50 dark:bg-black/30 rounded-[3rem] overflow-hidden flex items-center justify-center border-2 border-dashed border-gray-200 dark:border-white/10 relative">
              {resultImage ? (
                <img src={resultImage} alt="AI Result" className="w-full h-full object-contain" />
              ) : (
                <div className="text-center px-8">
                  <div className="w-20 h-20 bg-gray-200 dark:bg-white/5 rounded-full flex items-center justify-center mx-auto mb-6">
                    <ImageIcon className="text-gray-400" />
                  </div>
                  <h3 className="text-xl font-black mb-2 uppercase opacity-40">Concept Preview</h3>
                  <p className="text-sm text-gray-400">Your generated visualization will appear here.</p>
                </div>
              )}
            </div>
          </>
        ) : (
          <div className="lg:col-span-12 flex flex-col h-[700px] bg-white dark:bg-black/20 border border-gray-100 dark:border-white/5 rounded-[3rem] overflow-hidden">
            <div className="p-6 border-b border-gray-100 dark:border-white/5 bg-gray-50/50 dark:bg-white/5 flex items-center gap-3">
              <div className="w-3 h-3 rounded-full bg-forest animate-pulse" />
              <span className="text-xs font-black uppercase tracking-widest">Live: Compassionate Guide</span>
            </div>
            <div className="flex-1 overflow-y-auto p-8 space-y-6">
              {chatMessages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center max-w-sm mx-auto">
                  <MessageSquare size={48} className="text-forest/30 mb-6" />
                  <h3 className="text-2xl font-black mb-4 uppercase">How can I assist you today?</h3>
                  <p className="text-sm text-gray-400 leading-relaxed italic">"Whether it's grief support or planning a legacy, I'm here to guide you with care."</p>
                </div>
              )}
              {chatMessages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] p-6 rounded-3xl text-sm leading-relaxed ${
                    m.role === 'user' ? 'bg-forest text-white' : 'bg-gray-100 dark:bg-white/5'
                  }`}>
                    {m.text}
                  </div>
                </div>
