const LiveVoiceSupport = ({ isOpen, onClose }: { isOpen: boolean, onClose: () => void }) => {
  const [status, setStatus] = useState<'Connecting' | 'Listening' | 'Speaking' | 'Inactive'>('Inactive');
  const [transcription, setTranscription] = useState('');
  const [bars, setBars] = useState<number[]>(new Array(12).fill(10));

  // Refs for audio processing
  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const sessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  useEffect(() => {
    if (isOpen) {
      startSession();
    } else {
      stopSession();
    }
    return () => stopSession();
  }, [isOpen]);

  const startSession = async () => {
    setStatus('Connecting');
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = inputCtx;
      outputAudioContextRef.current = outputCtx;

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setStatus('Listening');
            const source = inputCtx.createMediaStreamSource(stream);
            const processor = inputCtx.createScriptProcessor(4096, 1, 1);
            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              // Simple visualization
              const vol = Math.max(...inputData.map(Math.abs)) * 100;
              setBars(prev => prev.map(() => 5 + Math.random() * (vol + 5)));

              const pcmBlob = createBlob(inputData);
              sessionPromise.then(session => session.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(processor);
            processor.connect(inputCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.modelTurn?.parts[0]?.inlineData?.data) {
              setStatus('Speaking');
              const base64 = message.serverContent.modelTurn.parts[0].inlineData.data;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputCtx.currentTime);
              const buffer = await decodeAudioData(decode(base64), outputCtx, 24000, 1);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                if (sourcesRef.current.size === 0) setStatus('Listening');
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += buffer.duration;
              sourcesRef.current.add(source);
            }
            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
            if (message.serverContent?.outputTranscription) {
                setTranscription(prev => (prev + " " + message.serverContent?.outputTranscription?.text).trim());
            }
          },
          onerror: (e) => {
            console.error('Live API Error:', e);
            setStatus('Inactive');
          },
          onclose: () => setStatus('Inactive')
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          systemInstruction: "You are the CloverLeaf Voice Support. Your goal is to provide immediate, calm, and professional assistance to those in grief or planning a legacy. Be brief, dignified, and architectural in your descriptions.",
          outputAudioTranscription: {}
        }
      });
      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error('Session failed:', err);
      setStatus('Inactive');
    }
  };

  const stopSession = () => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (audioContextRef.current) audioContextRef.current.close();
    if (outputAudioContextRef.current) outputAudioContextRef.current.close();
    setStatus('Inactive');
    setTranscription('');
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-md px-4">
      <div className="bg-white dark:bg-midnight-green w-full max-w-lg rounded-[3rem] p-12 text-center relative overflow-hidden shadow-2xl border border-white/10">
        <button onClick={onClose} className="absolute top-8 right-8 p-2 rounded-full hover:bg-gray-100 dark:hover:bg-white/5 transition-colors">
          <X size={24} />
        </button>
        <div className="flex justify-center mb-12">
          <div className="w-40 h-40 bg-forest rounded-full flex items-center justify-center text-white relative">
            <div className={`absolute inset-0 bg-forest rounded-full ${status !== 'Inactive' ? 'animate-ping' : ''} opacity-20`} />
            {status === 'Speaking' ? <Volume2 size={56} /> : <Mic size={56} />}
          </div>
        </div>
        <h3 className="text-3xl font-black mb-4 uppercase tracking-tighter">{status}</h3>
        <p className="text-gray-400 text-sm mb-12 leading-relaxed h-12 overflow-hidden">
          {transcription || "Listening for your voice..."}
        </p>
        <div className="flex items-center justify-center gap-2 h-16 mb-12">
          {bars.map((h, i) => (
            <div 
              key={i} 
              className="waveform-bar" 
              style={{ height: `${h}px`, transition: 'height 0.1s ease' }} 
            />
          ))}
        </div>
        <div className="flex gap-4">
          <button 
            onClick={onClose} 
            className="flex-1 py-5 bg-red-500/10 text-red-500 border border-red-500/20 rounded-2xl font-black text-sm uppercase hover:bg-red-500 hover:text-white transition-all"
          >
            End Conversation
          </button>
        </div>
      </div>
    </div>
  );
};

const Footer = () => (
  <footer className="bg-gray-50 dark:bg-black/50 border-t border-gray-200 dark:border-gray-800 py-16 px-4">
    <div className="max-w-7xl mx-auto grid grid-cols-1 md:grid-cols-4 gap-12">
