          <span className="w-2 h-2 rounded-full bg-red-500 animate-pulse" />
          Urgent Support
        </h4>
        <p className="text-xs text-gray-500 dark:text-gray-400 mb-6">24/7 Professional grief support and immediate assistance.</p>
        <button className="w-full py-3 bg-forest text-white rounded-xl font-black text-sm flex items-center justify-center gap-2 hover:scale-[1.02] active:scale-[0.98] transition-transform shadow-lg shadow-forest/20">
          <Phone size={16} /> CALL NOW
        </button>
      </div>
    </div>
  </footer>
);

// --- Main App ---

const App = () => {
