const MemorialAIPage = () => {
  const [activeTab, setActiveTab] = useState<'generate' | 'chat'>('generate');
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const [chatMessages, setChatMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [chatInput, setChatInput] = useState('');

  const generateConcept = async () => {
    if (!prompt) return;
    setIsGenerating(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: [{ text: `High-fidelity architectural concept for a memorial tombstone or funeral arrangement. Style: Modern Compassion. Subject: ${prompt}. Elegant, detailed, serene lighting.` }] },
        config: { imageConfig: { aspectRatio: "1:1" } }
      });
      const part = response.candidates[0].content.parts.find(p => p.inlineData);
      if (part?.inlineData) setResultImage(`data:image/png;base64,${part.inlineData.data}`);
    } catch (err) {
      console.error(err);
      alert('Design generation failed. Please try again.');
    } finally {
      setIsGenerating(false);
    }
  };

  const handleChat = async () => {
    if (!chatInput) return;
    const userMsg = chatInput;
    setChatInput('');
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMsg,
        config: { systemInstruction: "You are the CloverLeaf Compassionate Guide. You help families with funeral planning, grief support, and memorial ideas. Your tone is dignified, architectural, and deeply empathetic. You focus on 'Modern Compassion'." }
      });
      setChatMessages(prev => [...prev, { role: 'ai', text: response.text || "I'm here to listen." }]);
