            onClick={() => setActiveTab('generate')}
            className={`flex-1 md:flex-none px-8 py-3 rounded-xl text-xs font-black transition-all uppercase tracking-widest ${activeTab === 'generate' ? 'bg-white dark:bg-forest text-black dark:text-white shadow-sm' : 'opacity-50'}`}
