          >
            Guide
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 min-h-[600px]">
        {activeTab === 'generate' ? (
          <>
            <div className="lg:col-span-4 space-y-6">
